import type { paths } from './generated/http';

/**
 * The server's routes as its own schema says them, generated by `pnpm
 * api:types`: which answer which method, with what, and what each takes in.
 * The page's requests are held to these, so a route the server does not
 * have, or a part it does not take, does not compile.
 */

/** How the server's schema names the methods the page asks with. */
export type Method = 'get' | 'put' | 'post' | 'delete';

/** The status a route answers with when it did what was asked and has something to say. */
type Done = 200;
/** The status a route answers with when it did what was asked and has nothing to say. */
type DoneWithNothingToSay = 204;
/** The media type a route's JSON is written in. */
export type JsonMediaType = 'application/json';

/** What a route answers when it does what was asked and sends JSON. */
type JsonReply<Body> = Record<Done, { content: Record<JsonMediaType, Body> }>;
/** What a route answers when it does what was asked and sends nothing. */
type NoReply = Record<DoneWithNothingToSay, unknown>;

/** The path of every route that answers a method, with a reply of a kind. */
type RouteAnswering<Verb extends Method, Reply> = {
	[Path in keyof paths]: paths[Path][Verb] extends { responses: Reply } ? Path : never;
}[keyof paths];

/** Every route that answers a method with JSON. */
export type JsonRoute<Verb extends Method> = RouteAnswering<Verb, JsonReply<unknown>>;
/** Every route that answers a method with nothing but having done it. */
export type SilentRoute<Verb extends Method> = RouteAnswering<Verb, NoReply>;
/** Every route the browser fetches itself, as an image is drawn: one that answers GET with a file, not JSON. */
export type FileRoute = Exclude<RouteAnswering<'get', object>, JsonRoute<'get'>>;

/** What the server's schema says of one method of one route. */
type Operation<Verb extends Method, Path extends keyof paths> = paths[Path][Verb];

/** The JSON a route answers with when it does what was asked. */
export type ReplyOf<Verb extends Method, Path extends keyof paths> =
	Operation<Verb, Path> extends { responses: JsonReply<infer Body> } ? Body : never;

/** What a route takes in its query, as its schema names it. */
export type Query<Verb extends Method, Path extends keyof paths> =
	Operation<Verb, Path> extends { parameters: { query?: infer Taken } } ? Taken : never;

/** What a route takes in its path: the names its path has a place for. */
type NamedInPath<Verb extends Method, Path extends keyof paths> =
	Operation<Verb, Path> extends { parameters: { path?: infer Named } } ? Named : never;

/** What a route takes as its body: JSON of its model, or a file as it is, an image say. */
type Body<Verb extends Method, Path extends keyof paths> =
	Operation<Verb, Path> extends { requestBody: { content: Record<JsonMediaType, infer Json> } }
		? Json
		: Operation<Verb, Path> extends { requestBody: { content: object } }
			? Blob
			: never;

/** A part of a request: given when the route takes it, never when it does not. */
type Part<Name extends string, Taken> = [Taken] extends [never] ? { [Key in Name]?: never } : { [Key in Name]: Taken };

/** Each part a request to a route carries, where the route takes it: its query, the names in its path, its body. */
export type Parts<Verb extends Method, Path extends keyof paths> = Part<'query', Query<Verb, Path>> &
	Part<'pathParameters', NamedInPath<Verb, Path>> &
	Part<'body', Body<Verb, Path>>;
